'use client'

import { useEffect, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'
import { useSearchParams } from 'next/navigation'
import ABI from './../abi/giftmoji.json'
import toast, { Toaster } from 'react-hot-toast'
import Web3 from 'web3'
import styles from './Page.module.scss'
import Heading from './../components/Heading'


export default function Page() {
  const [emoji, setEmoji] = useState([])
  const [react, setReact] = useState([])
  const [profiles, setProfiles] = useState()
  let [searchParams] = useSearchParams()
  // const auth = useUpProvider()
  const web3Readonly = new Web3(process.env.NEXT_PUBLIC_LUKSO_PROVIDER)
  const _ = web3Readonly.utils
  const contractReadonly = new web3Readonly.eth.Contract(ABI, process.env.NEXT_PUBLIC_CONTRACT)

  const getAllEmoji = async () => await contractReadonly.methods.getAllEmoji().call()

  const getAllUserReaction = async () => await contractReadonly.methods.getAllUserReaction(`0x0D5C8B7cC12eD8486E1E0147CC0c3395739F138d`).call()//${auth.contextAccounts[0]}

  const action = async (e, emoji) => {
    const t = toast.loading(`Waiting for transaction's confirmation`)

    const message = prompt(`Please enter a message:`)

    const web3 = new Web3(auth.provider)
    const contract = new web3.eth.Contract(ABI, process.env.VITE_CONTRACT)

    try {
      // window.lukso.request({ method: 'eth_requestAccounts' }).then((accounts) => {
      contract.methods
        .react(`${auth.contextAccounts[0]}`, emoji.emojiId, _.toHex(message))
        .send({
          from: auth.accounts[0],
          value: emoji.price,
        })
        .then((res) => {
          console.log(res)

          toast.success(`Done`)
          toast.dismiss(t)

          party.confetti(document.body, {
            count: party.variation.range(20, 40),
          })
        })
        .catch((error) => {
          toast.dismiss(t)
        })
      // })
    } catch (error) {
      console.log(error)
      toast.dismiss(t)
    }
  }

  const getIPFS = async (CID) => {
    let requestOptions = {
      method: 'GET',
      redirect: 'follow',
    }
    const response = await fetch(`${process.env.VITE_IPFS_GATEWAY}${CID}`, requestOptions)
    if (!response.ok) return { result: false } //throw new Response('Failed to get data', { status: 500 })
    return response.json()
  }


  const getProfile = async (addr) => {
    const myHeaders = new Headers()
    myHeaders.append('Content-Type', `application/json`)
    myHeaders.append('Accept', `application/json`)

    const requestOptions = {
      method: 'POST',
      headers: myHeaders,
      body: JSON.stringify({
        query: `query MyQuery {
  search_profiles(
    args: {search: "${addr}"}
    limit: 1
  ) {
    fullName
    name
    description
    id
    profileImages {
      src
    }
  }
}`,
      }),
    }
    const response = await fetch(`${process.env.NEXT_PUBLIC_API_ENDPOINT}`, requestOptions)
    if (!response.ok) {
      throw new Response('Failed to ', { status: 500 })
    }
    const data = await response.json()
    return data
  }


  useEffect(() => {
    getAllEmoji().then((res) => {
      console.log(res)
      if (res.length < 1) return
      setEmoji(res)
    })

  }, [])

  return (
    <div className={`${styles.page} ms-motion-slideDownIn mt-20`} data-width={`large`}>
      <div className={`__container`} data-width={`large`}>
        <div className={`${styles.grid} grid grid--fit w-100`} style={{ '--data-width': `100px` }}>
          {emoji.length === 0 && (
            <div className={`d-flex align-items-center justify-content-between w-100`} style={{ '--data-width': `58px` }}>
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
              <div className={`shimmer ${styles.shimmer}`} />
            </div>
          )}

          {emoji &&
            emoji.map((item, i) => {
              return (
                <div key={i} data-name={item.name} className={`${styles.emoji} d-flex flex-column align-items-center justify-content-between`} title={item.name} onClick={(e) => action(e, item)}>
                  <figure className={`${styles.emoji__icon}`}>
                    <img
                    className={`animate__animated animate__heartBeat`}
                      src={`/emoji/${item.emoji}.svg`}
                      alt={`${process.env.NEXT_PUBLIC_NAME}`}
                      width={32}
                      height={32}
                      title={(react && react.length > 0 && react.filter((filterItem, i) => filterItem.emojiId === item.emojiId).length) || 0}
                    />
                  </figure>

                  <b className={`text-center`}>
                    <span>⏣ </span>
                    <span>{_.fromWei(item.price, `ether`)}</span>
                  </b>
                </div>
              )
            })}
        </div>
      </div>
    </div>
  )
}
